import random


class BCRBatchBuilder:
    def __init__(self, problems: list[tuple] = None):
        # problems is [(question, difficulty), ...]
        self.problems = []
        if problems:
            for q, d in problems:
                self.add_problem(q, d)

    def add_problem(self, question: str, difficulty: float):
        self.problems.append({'question': question, 'difficulty': difficulty})

    def _easy(self):
        return [p for p in self.problems if p['difficulty'] < 0.5]

    def _hard(self):
        return [p for p in self.problems if p['difficulty'] >= 0.5]

    def build_batch(self, batch_size: int = 8) -> list[dict]:
        easy = self._easy()
        hard = self._hard()
        half = batch_size // 2
        batch = []
        # Sample with replacement only if a pool is smaller than needed
        for pool, n in ((easy, half), (hard, batch_size - half)):
            if not pool or n <= 0:
                continue
            if len(pool) >= n:
                chosen = random.sample(pool, n)
            else:
                chosen = list(pool) + [random.choice(pool) for _ in range(n - len(pool))]
            batch.extend(dict(p) for p in chosen)
        random.shuffle(batch)
        return batch

    def stats(self) -> dict:
        easy = len(self._easy())
        hard = len(self._hard())
        return {'total': len(self.problems), 'easy_count': easy, 'hard_count': hard}


# Test it:
builder = BCRBatchBuilder([("What is 2+2?", 0.1), ("Prove P=NP", 0.95),
                           ("Sort a list", 0.3), ("Solve integral", 0.8)])
print(builder.stats())
batch = builder.build_batch(4)
print(len(batch))
print(all('question' in p and 'difficulty' in p for p in batch))
